// AG Grid v36. Infinite Row Model: Community. Loads rows from the server in blocks as the user scrolls.
import { useMemo } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import { AllCommunityModule } from "ag-grid-community";
import type { ColDef, IDatasource, IGetRowsParams } from "ag-grid-community";

const modules = [AllCommunityModule];

interface Order { id: number; customer: string; status: string; total: number }

export function LargeOrdersGrid() {
  const columnDefs = useMemo<ColDef<Order>[]>(() => [
    { field: "id" }, { field: "customer" }, { field: "status" }, { field: "total" },
  ], []);

  // Hypothetical endpoint: returns { rows, lastRow } for the requested range
  const datasource = useMemo<IDatasource>(() => ({
    getRows: async (params: IGetRowsParams) => {
      try {
        // The grid cannot sort rows it has not loaded, so the server applies the sort model
        const sort = encodeURIComponent(JSON.stringify(params.sortModel));
        const res = await fetch(`/api/orders?start=${params.startRow}&end=${params.endRow}&sort=${sort}`);
        const { rows, lastRow } = await res.json();
        params.successCallback(rows, lastRow);
      } catch {
        params.failCallback();
      }
    },
  }), []);

  return (
    <AgGridProvider modules={modules}>
      <div style={{ height: 600 }}>
        <AgGridReact<Order>
          columnDefs={columnDefs}
          rowModelType="infinite"
          datasource={datasource}
          cacheBlockSize={100}
          maxBlocksInCache={10}
          rowBuffer={10}
        />
      </div>
    </AgGridProvider>
  );
}
